=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO peripheral with interrupts.
// Implements microarchitecture.md (approved) for interface_spec.md (approved).
`default_nettype none
module apb_gpio #(
  parameter integer ADDR_WIDTH = 8,
  parameter integer N          = 8
) (
  input  wire                  pclk,
  input  wire                  presetn,
  input  wire [ADDR_WIDTH-1:0] paddr,
  input  wire                  psel,
  input  wire                  penable,
  input  wire                  pwrite,
  input  wire [31:0]           pwdata,
  input  wire [3:0]            pstrb,
  output reg  [31:0]           prdata,
  output wire                  pready,
  output wire                  pslverr,
  input  wire [N-1:0]          gpio_in,
  output wire [N-1:0]          gpio_out,
  output wire [N-1:0]          gpio_oe,
  output wire                  irq
);

  // Bits 0..N-1 set: the pins that exist.
  localparam [31:0] PINS = (N >= 32) ? 32'hFFFF_FFFF : ((32'h1 << N) - 32'h1);

  localparam [3:0] IDX_OUT    = 4'd0;
  localparam [3:0] IDX_DIR    = 4'd1;
  localparam [3:0] IDX_IN     = 4'd2;
  localparam [3:0] IDX_RISE   = 4'd3;
  localparam [3:0] IDX_FALL   = 4'd4;
  localparam [3:0] IDX_HIGH   = 4'd5;
  localparam [3:0] IDX_LOW    = 4'd6;
  localparam [3:0] IDX_EN     = 4'd7;
  localparam [3:0] IDX_STATUS = 4'd8;

  // ---------------- APB decode (no state machine) ----------------
  wire       access     = psel & penable;
  wire [3:0] idx        = paddr[5:2];
  wire       upper_zero = ~|paddr[ADDR_WIDTH-1:6];
  wire       mapped     = (paddr[1:0] == 2'b00) & upper_zero & (idx <= IDX_STATUS);
  wire       wr         = access & pwrite & mapped;
  wire       rd         = access & ~pwrite & mapped;

  assign pready  = 1'b1;
  assign pslverr = access & (~mapped | (pwrite & (idx == IDX_IN)));

  wire [31:0] mask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;

  // ---------------- Registers ----------------
  reg [31:0] data_out;
  reg [31:0] dir;
  reg [31:0] in_q;
  reg [31:0] in_prev;
  reg [31:0] intr_rise;
  reg [31:0] intr_fall;
  reg [31:0] intr_high;
  reg [31:0] intr_low;
  reg [31:0] intr_en;
  reg [31:0] status;

  // gpio_in widened to 32 bits, zeros above N.
  wire [31:0] in_w;
  genvar g;
  generate
    for (g = 0; g < 32; g = g + 1) begin : g_in
      if (g < N) begin : g_pin
        assign in_w[g] = gpio_in[g];
      end else begin : g_nopin
        assign in_w[g] = 1'b0;
      end
    end
  endgenerate

  // ---------------- Detection ----------------
  wire [31:0] rise     = in_q & ~in_prev;
  wire [31:0] fall     = ~in_q & in_prev;
  wire [31:0] detected = ((rise & intr_rise) | (fall & intr_fall)
                        | (in_q & intr_high) | (~in_q & intr_low)) & PINS;
  wire [31:0] clear    = (wr && (idx == IDX_STATUS)) ? (pwdata & mask) : 32'h0;

  always @(posedge pclk) begin
    if (!presetn) begin
      data_out  <= 32'h0;
      dir       <= 32'h0;
      in_q      <= 32'h0;
      in_prev   <= 32'h0;
      intr_rise <= 32'h0;
      intr_fall <= 32'h0;
      intr_high <= 32'h0;
      intr_low  <= 32'h0;
      intr_en   <= 32'h0;
      status    <= 32'h0;
    end else begin
      in_q    <= in_w;
      in_prev <= in_q;
      // Detection is ORed last: a detection beats a clear.
      status  <= (status & ~clear) | detected;
      if (wr) begin
        case (idx)
          IDX_OUT:  data_out  <= (data_out  & ~mask) | (pwdata & mask);
          IDX_DIR:  dir       <= (dir       & ~mask) | (pwdata & mask);
          IDX_RISE: intr_rise <= (intr_rise & ~mask) | (pwdata & mask);
          IDX_FALL: intr_fall <= (intr_fall & ~mask) | (pwdata & mask);
          IDX_HIGH: intr_high <= (intr_high & ~mask) | (pwdata & mask);
          IDX_LOW:  intr_low  <= (intr_low  & ~mask) | (pwdata & mask);
          IDX_EN:   intr_en   <= (intr_en   & ~mask) | (pwdata & mask);
          default:  ; // DATA_IN read only, INTR_STATUS handled by clear
        endcase
      end
    end
  end

  // ---------------- Read mux ----------------
  always @(*) begin
    prdata = 32'h0;
    if (rd) begin
      case (idx)
        IDX_OUT:    prdata = data_out;
        IDX_DIR:    prdata = dir;
        IDX_IN:     prdata = in_q;
        IDX_RISE:   prdata = intr_rise;
        IDX_FALL:   prdata = intr_fall;
        IDX_HIGH:   prdata = intr_high;
        IDX_LOW:    prdata = intr_low;
        IDX_EN:     prdata = intr_en;
        IDX_STATUS: prdata = status;
        default:    prdata = 32'h0;
      endcase
    end
  end

  assign gpio_out = data_out[N-1:0];
  assign gpio_oe  = dir[N-1:0];
  assign irq      = |(status & intr_en);

`ifdef FORMAL
  // Design-intent assertions (immediate).
  always @(*) begin
    assert (pready);
    if (!access) assert (prdata == 32'h0);
    if (!access) assert (!pslverr);
    assert ((data_out & ~PINS) == 32'h0);
    assert ((dir & ~PINS) == 32'h0);
    assert ((status & ~PINS) == 32'h0);
    assert ((in_q & ~PINS) == 32'h0);
  end
`endif

endmodule
`default_nettype wire
=== END FILE ===
