// apb_gpio_tb: directed self-checking testbench, lanes at N=8 and N=32.
`timescale 1ns/1ps
module apb_gpio_tb;

  reg clk = 1'b0;
  always #5 clk = ~clk;

  reg         presetn;
  reg  [7:0]  paddr;
  reg         psel, penable, pwrite;
  reg  [31:0] pwdata;
  reg  [3:0]  pstrb;
  reg  [31:0] gin;

  wire [31:0] prdata8, prdata32;
  wire        pready8, pready32, pslverr8, pslverr32;
  wire [7:0]  gout8, goe8;
  wire [31:0] gout32, goe32;
  wire        irq8, irq32;

  localparam [31:0] M8 = 32'h0000_00FF;

  integer passed;
  integer failed;
  integer k;
  reg [3:0]  ridx;
  reg [7:0]  cur_addr;
  reg [31:0] e [0:8];  // model: 0 OUT,1 DIR,2 IN,3 RISE,4 FALL,5 HIGH,6 LOW,7 EN,8 STATUS
  reg [8*64-1:0] nonce;

  apb_gpio #(.ADDR_WIDTH(8), .N(8)) dut8 (
    .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata8),
    .pready(pready8), .pslverr(pslverr8), .gpio_in(gin[7:0]),
    .gpio_out(gout8), .gpio_oe(goe8), .irq(irq8));

  apb_gpio #(.ADDR_WIDTH(8), .N(32)) dut32 (
    .pclk(clk), .presetn(presetn), .paddr(paddr), .psel(psel), .penable(penable),
    .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata32),
    .pready(pready32), .pslverr(pslverr32), .gpio_in(gin),
    .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32));

  function [31:0] smask(input [3:0] s);
    smask = {{8{s[3]}}, {8{s[2]}}, {8{s[1]}}, {8{s[0]}}};
  endfunction

  function [31:0] merge(input [31:0] old, input [31:0] d, input [3:0] s);
    merge = (old & ~smask(s)) | (d & smask(s));
  endfunction

  function [3:0] rwidx(input integer i);
    case (i)
      0: rwidx = 4'd0;
      1: rwidx = 4'd1;
      2: rwidx = 4'd3;
      3: rwidx = 4'd4;
      4: rwidx = 4'd5;
      5: rwidx = 4'd6;
      default: rwidx = 4'd7;
    endcase
  endfunction

  task chk(input [8*24-1:0] what, input [31:0] got, input [31:0] exp);
    begin
      if (got === exp) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("FAIL %0s (addr %h) at %0t: got %h expected %h", what, cur_addr, $time, got, exp);
      end
    end
  endtask

  task chk_idle;
    begin
      chk("idle prdata8",  prdata8,  32'h0);
      chk("idle prdata32", prdata32, 32'h0);
      chk("idle pslverr",  {30'b0, pslverr8, pslverr32}, 32'h0);
    end
  endtask

  task apb_wr_p(input [7:0] a, input [31:0] d, input [3:0] s, input err,
                input setpins, input [31:0] pins);
    begin
      cur_addr = a;
      @(negedge clk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b1; paddr = a; pwdata = d; pstrb = s;
      if (setpins) gin = pins;
      #1 chk_idle;
      @(negedge clk);
      penable = 1'b1;
      #1;
      chk("pready", {30'b0, pready8, pready32}, 32'h3);
      chk("wr pslverr", {30'b0, pslverr8, pslverr32}, err ? 32'h3 : 32'h0);
      @(negedge clk);
      psel = 1'b0; penable = 1'b0; pwrite = 1'b0; pstrb = 4'h0; pwdata = 32'h0;
      #1 chk_idle;
    end
  endtask

  task apb_write(input [7:0] a, input [31:0] d, input [3:0] s, input err);
    apb_wr_p(a, d, s, err, 1'b0, 32'h0);
  endtask

  task apb_read(input [7:0] a, input [31:0] exp, input err);
    begin
      cur_addr = a;
      @(negedge clk);
      psel = 1'b1; penable = 1'b0; pwrite = 1'b0; paddr = a; pwdata = 32'h0; pstrb = 4'h0;
      #1 chk_idle;
      @(negedge clk);
      penable = 1'b1;
      #1;
      chk("pready", {30'b0, pready8, pready32}, 32'h3);
      chk("prdata8",  prdata8,  exp & M8);
      chk("prdata32", prdata32, exp);
      chk("rd pslverr", {30'b0, pslverr8, pslverr32}, err ? 32'h3 : 32'h0);
      @(negedge clk);
      psel = 1'b0; penable = 1'b0;
      #1 chk_idle;
    end
  endtask

  task wreg(input [3:0] i, input [31:0] d, input [3:0] s);
    begin
      e[i] = merge(e[i], d, s);
      apb_write({2'b00, i, 2'b00}, d, s, 1'b0);
    end
  endtask

  task rreg(input [3:0] i);
    apb_read({2'b00, i, 2'b00}, e[i], 1'b0);
  endtask

  task chk_pins;
    begin
      chk("gpio_out8",  {24'b0, gout8}, e[0] & M8);
      chk("gpio_out32", gout32,         e[0]);
      chk("gpio_oe8",   {24'b0, goe8},  e[1] & M8);
      chk("gpio_oe32",  goe32,          e[1]);
      chk("irq8",  {31'b0, irq8},  {31'b0, |(e[8] & e[7] & M8)});
      chk("irq32", {31'b0, irq32}, {31'b0, |(e[8] & e[7])});
    end
  endtask

  task set_pins(input [31:0] v);
    begin
      @(negedge clk);
      gin = v;
    end
  endtask

  task tick(input integer n);
    repeat (n) @(negedge clk);
  endtask

  task model_reset;
    for (k = 0; k < 9; k = k + 1) e[k] = 32'h0;
  endtask

  task read_all;
    for (k = 0; k < 9; k = k + 1) rreg(k[3:0]);
  endtask

  initial begin
    passed = 0; failed = 0; cur_addr = 8'h00;
    presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
    paddr = 8'h00; pwdata = 32'h0; pstrb = 4'h0; gin = 32'h0;
    model_reset;

    // 1. Reset values
    tick(3);
    chk_pins;
    presetn = 1'b1;
    chk_idle;
    read_all;
    chk_pins;

    // 2. Read/write registers, partial strobes, bits above N.
    //    INTR_LOW all ones with pins low also sets every status bit (low level).
    for (k = 0; k < 7; k = k + 1) begin
      ridx = rwidx(k);
      wreg(ridx, 32'hFFFF_FFFF, 4'hF);
      if (ridx == 4'd6) e[8] = 32'hFFFF_FFFF;
      rreg(ridx); chk_pins;
      wreg(ridx, 32'h1234_5678, 4'b0101);
      rreg(ridx); chk_pins;
      wreg(ridx, 32'h8765_4321, 4'b1010);
      rreg(ridx); chk_pins;
      wreg(ridx, 32'h0, 4'hF);
      rreg(ridx); chk_pins;
    end
    rreg(4'd8);
    apb_write(8'h20, 32'hFFFF_FFFF, 4'hF, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);

    // 3. gpio_out and gpio_oe
    wreg(4'd0, 32'hA5A5_5AC3, 4'hF);
    wreg(4'd1, 32'h0F0F_F00F, 4'hF);
    rreg(4'd0); rreg(4'd1);
    chk_pins;

    // 4. DATA_IN, read only
    set_pins(32'h8000_00A5);
    e[2] = 32'h8000_00A5;
    rreg(4'd2);
    apb_write(8'h08, 32'hFFFF_FFFF, 4'hF, 1'b1);
    rreg(4'd2);
    set_pins(32'h0);
    e[2] = 32'h0;
    tick(1);
    rreg(4'd2);

    // 5. PSLVERR policy: unmapped writes change nothing, unmapped reads return 0
    apb_write(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_read (8'h24, 32'h0, 1'b1);
    apb_write(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h44, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_write(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
    apb_read (8'h02, 32'h0, 1'b1);
    apb_read (8'h23, 32'h0, 1'b1);
    apb_read (8'h40, 32'h0, 1'b1);
    apb_read (8'hFC, 32'h0, 1'b1);
    read_all;
    chk_pins;

    // 6. Rising edge fires once
    wreg(4'd3, 32'h0010_0001, 4'hF);
    set_pins(32'h0010_0001);
    tick(2);
    e[8] = 32'h0010_0001;
    rreg(4'd8); chk_pins;
    apb_write(8'h20, 32'h0010_0001, 4'hF, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);
    tick(2);
    rreg(4'd8);
    wreg(4'd3, 32'h0, 4'hF);
    set_pins(32'h0);
    tick(2);
    rreg(4'd8);

    // 7. Falling edge
    set_pins(32'h8000_0002);
    tick(2);
    wreg(4'd4, 32'h8000_0002, 4'hF);
    rreg(4'd8);
    set_pins(32'h0);
    tick(2);
    e[8] = 32'h8000_0002;
    rreg(4'd8);
    apb_write(8'h20, 32'h8000_0002, 4'hF, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);
    wreg(4'd4, 32'h0, 4'hF);

    // 8. High level sets again after a clear
    wreg(4'd5, 32'h0100_0004, 4'hF);
    rreg(4'd8);
    set_pins(32'h0100_0004);
    tick(2);
    e[8] = 32'h0100_0004;
    rreg(4'd8);
    apb_write(8'h20, 32'h0100_0004, 4'hF, 1'b0);
    rreg(4'd8);
    set_pins(32'h0);
    tick(2);
    rreg(4'd8);
    apb_write(8'h20, 32'h0100_0004, 4'hF, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);
    wreg(4'd5, 32'h0, 4'hF);

    // 9. Low level sets again after a clear
    wreg(4'd6, 32'h0200_0008, 4'hF);
    e[8] = 32'h0200_0008;
    tick(1);
    rreg(4'd8);
    apb_write(8'h20, 32'h0200_0008, 4'hF, 1'b0);
    rreg(4'd8);
    set_pins(32'h0200_0008);
    tick(2);
    apb_write(8'h20, 32'h0200_0008, 4'hF, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);
    wreg(4'd6, 32'h0, 4'hF);
    set_pins(32'h0);
    tick(2);
    rreg(4'd8);

    // 10. Write-1-to-clear of some pending bits only
    wreg(4'd3, 32'h000F_000F, 4'hF);
    set_pins(32'h000F_000F);
    tick(2);
    e[8] = 32'h000F_000F;
    rreg(4'd8);
    apb_write(8'h20, 32'h0005_0005, 4'b0001, 1'b0);
    e[8] = 32'h000F_000A;
    rreg(4'd8);
    apb_write(8'h20, 32'hFFFF_FFFF, 4'b0000, 1'b0);
    rreg(4'd8);
    apb_write(8'h20, 32'h000F_000F, 4'hF, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);
    wreg(4'd3, 32'h0, 4'hF);
    set_pins(32'h0);
    tick(2);

    // 11. Interrupt mask
    wreg(4'd3, 32'h1000_0020, 4'hF);
    set_pins(32'h1000_0020);
    tick(2);
    e[8] = 32'h1000_0020;
    rreg(4'd8); chk_pins;
    wreg(4'd7, 32'h1000_0000, 4'hF); chk_pins;
    wreg(4'd7, 32'h1000_0020, 4'hF); chk_pins;
    apb_write(8'h20, 32'h0000_0020, 4'b0001, 1'b0);
    e[8] = 32'h1000_0000;
    chk_pins; rreg(4'd8);
    apb_write(8'h20, 32'h1000_0000, 4'hF, 1'b0);
    e[8] = 32'h0;
    chk_pins; rreg(4'd8);
    wreg(4'd7, 32'h0, 4'hF);
    wreg(4'd3, 32'h0, 4'hF);
    set_pins(32'h0);
    tick(2);

    // 12. A detection beats a clear on the same edge
    wreg(4'd3, 32'h0000_0040, 4'hF);
    set_pins(32'h0000_0040);
    tick(2);
    e[8] = 32'h0000_0040;
    rreg(4'd8);
    set_pins(32'h0);
    tick(2);
    rreg(4'd8);
    apb_wr_p(8'h20, 32'h0000_0040, 4'h1, 1'b0, 1'b1, 32'h0000_0040);
    rreg(4'd8);
    apb_write(8'h20, 32'h0000_0040, 4'h1, 1'b0);
    e[8] = 32'h0;
    rreg(4'd8);
    wreg(4'd3, 32'h0, 4'hF);
    set_pins(32'h0);
    tick(2);

    // 13. Reset again
    wreg(4'd7, 32'h0000_0001, 4'hF);
    wreg(4'd6, 32'h0000_0001, 4'hF);
    tick(2);
    e[8] = 32'h0000_0001;
    rreg(4'd8);
    chk_pins;
    @(negedge clk);
    presetn = 1'b0;
    tick(3);
    model_reset;
    chk_pins;
    presetn = 1'b1;
    read_all;
    chk_pins;

    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 0;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
